import sys, json, math, re, collections, random
sys.path.insert(0,"/workspace")
from collections import Counter
from benchmark.evaluate import load_task
from benchmark.runtime.runs import load_config
from pathlib import Path
cfg=load_config(Path("/workspace/runs/config.yaml"))
ex=load_task("LawBench", cfg, "val")
print("val examples", len(ex), "keys", list(ex[0].keys()))
mem=json.load(open("/workspace/runs/84ec2cc228a15743611ceb178336561ddcb30aaa/LawBench/memory.json"))["examples"]

def parse_charges(text):
    t=text.strip()
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)",t)
    if m: t=m.group(1).strip()
    elif "罪名:" in t: t=t.split("罪名:")[-1]
    t=re.sub(r"<eoa>.*","",t).strip()
    for sep in [";","；",",","，","、"]:
        if sep in t: return {x.strip() for x in t.split(sep) if x.strip()}
    return {t} if t else set()

def ngrams(text,n=2):
    text=re.sub(r"\s+"," ",text).strip()
    return Counter(text[i:i+n] for i in range(len(text)-n+1))
def idf(docs):
    df=Counter()
    for d in docs: df.update(d.keys())
    total=max(len(docs),1)
    return {g: math.log((total+1)/(c+1))+1.0 for g,c in df.items()}
def wnorm(d,w): return math.sqrt(sum((c*w.get(g,1.0))**2 for g,c in d.items()))
def cos(q,d,w,qn,dn):
    if not qn or not dn: return 0.0
    return sum(c*d.get(g,0)*w.get(g,1.0)**2 for g,c in q.items())/(qn*dn)

qdocs=[ngrams(str(e.get("raw_question", e["input"]))) for e in mem]
w=idf(qdocs); N=len(mem)
mem_targets=[parse_charges(str(e["target"])) for e in mem]
# how often is a val target identical to some memory answer?
vals=[]
for e in ex:
    t=parse_charges(e["target"]); vals.append((e,t))
print("val targets equal to some memory answer:", sum(1 for e,t in vals if any(t==mt for mt in mem_targets)), "/", len(vals))

def predict_for(query, k, mode):
    q=ngrams(query); qn=wnorm(q,w)
    scores=[cos(q,d,w,qn,wnorm(d,w)) for d in qdocs]
    order=sorted(range(N), key=lambda i:(-scores[i], i))[:k]
    if mode=="top1": return set(mem_targets[order[0]])
    if mode=="union":
        s=set()
        for i in order: s|=mem_targets[i]
        return s
    if mode=="vote":
        acc=collections.defaultdict(float)
        for i in order:
            for c in mem_targets[i]: acc[c]+=scores[i]
        if not acc: return set()
        best=max(acc.values())
        return {c for c,v in acc.items() if v>=0.5*best}
    if mode=="intersect":
        s=set(mem_targets[order[0]])
        for i in order[1:]: s&=mem_targets[i]
        return s

for k in [1,3,5,10]:
    for mode in ["top1","union","vote"]:
        correct=0
        for e,t in vals:
            if predict_for(e["input"], k, mode)==t: correct+=1
        print(f"k={k} mode={mode}: exact {correct}/{len(vals)} = {correct/len(vals):.3f}")
